/** Exact per-post spans and a frozen mixed destination allowlist; no broad-host admission. */
function pl_require_self_links(string $text, array $actual, array $expected, array $allowed): void {
    pl_check(preg_match('/[\x{10000}-\x{10ffff}]/u', $text) === 0, 'unsupported_native_character');
    pl_check(array_is_list($actual) && array_is_list($expected) && count($expected) >= 1
        && count($expected) <= 33 && count($actual) === count($expected), 'native_autolinks_missing');
    usort($actual, static fn($a, $b) => ($a['from'] ?? -1) <=> ($b['from'] ?? -1));
    foreach ($expected as $i => $span) {
        $seen = $actual[$i];
        pl_check(is_array($seen) && count($seen) === 4 && array_diff(array_keys($seen), ['type','from','length','url']) === []
            && ($seen['type'] ?? null) === 'link' && ($seen['from'] ?? null) === $span['from']
            && ($seen['length'] ?? null) === $span['length'] && ($seen['url'] ?? null) === $span['url']
            && isset($allowed[$span['url']])
            && mb_substr($text, $span['from'], $span['length'], 'UTF-8') === $span['url'], 'native_autolink_mismatch');
    }
}

