function pl_self_test(): void {
    $p = pl_package(); $allowed = array_fill_keys($p['allowed_destinations'], true); $checks = 69;
    $reject = static function (callable $action, string $reason) use (&$checks): void {
        try { $action(); } catch (RuntimeException $error) {
            pl_check($error->getMessage() === $reason, 'self_test_wrong_refusal'); ++$checks; return;
        }
        throw new RuntimeException('self_test_missing_refusal');
    };
    foreach (['model-iphone-17','menu','models-index','service-display'] as $id) {
        $t = $p['posts'][$id]; $n = $t['after'];
        $reject(static fn() => pl_require_self_links($n['native_text'], [], $n['native_markup'], $allowed), 'native_autolinks_missing');
        $wrong = $n['native_markup']; $wrong[0]['url'] = 'https://example.com/';
        $reject(static fn() => pl_require_self_links($n['native_text'], $wrong, $n['native_markup'], $allowed), 'native_autolink_mismatch');
        $wrong = $n['native_markup']; $wrong[0]['from']++;
        $reject(static fn() => pl_require_self_links($n['native_text'], $wrong, $n['native_markup'], $allowed), 'native_autolink_mismatch');
        $wrong = $n['native_markup']; $wrong[0]['length']--;
        $reject(static fn() => pl_require_self_links($n['native_text'], $wrong, $n['native_markup'], $allowed), 'native_autolink_mismatch');
        $wrong = $n['native_markup']; $wrong[0]['type'] = 'strong';
        $reject(static fn() => pl_require_self_links($n['native_text'], $wrong, $n['native_markup'], $allowed), 'native_autolink_mismatch');
        $wrong = $n['native_markup']; $wrong[] = $wrong[0];
        $reject(static fn() => pl_require_self_links($n['native_text'], $wrong, $n['native_markup'], $allowed), 'native_autolinks_missing');
        $old = array_values(array_filter($t['before_markup'], static fn($s) => $s['type'] === 'link'));
        $reject(static fn() => pl_require_self_links($t['before_text'], $old, $old, $allowed), 'native_autolink_mismatch');
        $reject(static fn() => pl_require_self_links($n['native_text']."\u{1F600}", $n['native_markup'], $n['native_markup'], $allowed), 'unsupported_native_character');
        $missing = $allowed; unset($missing[$n['native_markup'][0]['url']]);
        $reject(static fn() => pl_require_self_links($n['native_text'], $n['native_markup'], $n['native_markup'], $missing), 'native_autolink_mismatch');
        pl_require_self_links($n['native_text'], array_reverse($n['native_markup']), $n['native_markup'], $allowed); ++$checks;
    }
    $x = $p['posts'][PL_CANARY_POST]; $legacyHash = str_repeat('a', 64);
    $request = pl_canary_request($x, pl_buttons($x), $legacyHash);
    $row = ['post_key' => PL_CANARY_KEY, 'operation' => 'links', 'state' => 'verified', 'write_attempts' => 1,
        'external_message_id' => $x['mid'], 'public_url' => $x['url'], 'request' => $request,
        'request_json' => pl_json($request), 'payload_sha256' => hash('sha256', pl_json($request)),
        'outcome' => ['readback' => true, 'native_text_sha256' => hash('sha256', $x['after']['native_text']),
            'native_markup_sha256' => pl_digest($x['after']['native_markup']), 'native_autolinks' => 4,
            'photo_preserved' => true, 'single_cta_preserved' => true, 'provider_acknowledged' => true, 'public_acceptance' => 'pending']];
    pl_require_canary_row($row, $x, $legacyHash); ++$checks;
    foreach (['state' => 'unknown', 'write_attempts' => 2, 'payload_sha256' => str_repeat('0', 64)] as $field => $value) {
        $bad = $row; $bad[$field] = $value;
        $reject(static fn() => pl_require_canary_row($bad, $x, $legacyHash), 'accepted_canary_operation_changed');
    }
    $reject(static fn() => pl_require_canary_row($row, $x, str_repeat('b', 64)), 'accepted_canary_operation_changed');
    $bad = $row; $bad['outcome']['photo_preserved'] = false;
    $reject(static fn() => pl_require_canary_row($bad, $x, $legacyHash), 'accepted_canary_outcome_changed');
    $reject(static fn() => pl_key(PL_CANARY_POST), 'fixed_target_invalid');
    pl_emit(['ok' => true, 'state' => 'remaining_source_checked', 'checks' => $checks, 'target_count' => 68,
        'readback_post_count' => 69, 'changed_link_count' => 268, 'total_link_count' => 272,
        'maximum_plain_body_characters' => max(array_map(static fn($t) => mb_strlen($t['after']['native_text'], 'UTF-8'), $p['posts'])),
        'shortened_copy_posts' => 4, 'canary_rewrite_available' => false, 'provider_writes' => 0, 'automatic_retry' => false]);
}

function pl_git(array $arguments): string {
    $pipes = []; $process = proc_open(['git', '-C', PL_ROOT, ...$arguments], [['pipe','r'],['pipe','w'],['pipe','w']], $pipes);
    pl_check(is_resource($process), 'checkout_read_failed'); fclose($pipes[0]);
    $out = stream_get_contents($pipes[1]); fclose($pipes[1]); stream_get_contents($pipes[2]); fclose($pipes[2]);
    pl_check(proc_close($process) === 0 && is_string($out), 'checkout_read_failed'); return trim($out);
}

