    foreach ($package['posts'] as $id => $target) {
        $currentPost = $id; $seen = $observe($target);
        if ($id === PL_CANARY_POST) {
            pl_check($seen['text'] === $target['after']['native_text'], 'accepted_canary_native_changed');
            pl_require_self_links($seen['text'], $seen['markup'], $target['after']['native_markup'], $allowed);
        } else {
            pl_check(hash('sha256', $seen['text']) === $target['before_text_sha256']
                && pl_digest($seen['markup']) === $target['before_markup_sha256'], 'native_preimage_changed');
        }
        $baseline[$id] = $seen;
    }
    $guard();
    pl_emit(['ok' => true, 'record' => 'remaining_preflight', 'post_count' => 69, 'verified_operations' => 363,
        'prior_operations_sha256' => $originalDigest, 'canary_operation_sha256' => pl_digest($canaryRow),
        'canary_payload_sha256' => $canaryRow['payload_sha256'], 'canary_source_sha' => PL_CANARY_SOURCE,
        'canary_receipt_sha256' => PL_CANARY_RECEIPT, 'canary_native_and_public_accepted' => true,
        'target_count' => 68, 'changed_link_count' => 268, 'provider_writes' => 0]);
    foreach ($package['write_order'] as $id) {
        $currentPost = $id; $target = $package['posts'][$id]; $next = $target['after']; $before = $baseline[$id];
        $acknowledged = null; $guard();
        $request = ['revision' => PL_REVISION, 'revision_sha256' => PL_PACKAGE_SHA256, 'target_post' => $id,
            'message_id' => $before['mid'], 'url' => $before['url'], 'prior_operations_sha256' => $originalDigest,
            'accepted_canary_source_sha' => PL_CANARY_SOURCE, 'accepted_canary_payload_sha256' => $canaryRow['payload_sha256'],
            'accepted_canary_receipt_sha256' => PL_CANARY_RECEIPT,
            'before_text_sha256' => $target['before_text_sha256'], 'before_markup_sha256' => $target['before_markup_sha256'],
            'preserved_photo_id' => $before['photo'], 'preserved_buttons' => $before['buttons'],
            'body' => $next['body'], 'native_text' => $next['native_text'], 'native_markup' => $next['native_markup']];
        $row = $store->prepare(pl_key($id), 'links', $request);
        pl_check($row['state'] === 'prepared' && (int)$row['write_attempts'] === 0, 'remaining_operation_already_attempted');
        $expectedRows[] = $row; $active = $row;
        // MAX permits at most two edits per second. Pace once, then recheck before claiming; never retry.
        usleep(600000);
        pl_invoke($pub, 'beforeWrite', $row, static function () use ($guard, $observe, $target, $before): void {
            $guard(); pl_check(pl_fingerprint($observe($target)) === pl_fingerprint($before), 'native_preimage_changed');
        });
        $store->rememberMessage($row, $before['mid'], $before['url']);
        // Exactly one text-only PUT per fixed post. Omitted attachments preserve image and CTA.
        ++$edits; $ack = $transport->edit($before['mid'], $next['body']);
        $acknowledged = AppleService39ChannelTransport::accepted($ack) && ($ack['data']['success'] ?? null) === true;
        $after = $observe($target);
        pl_check($after['text'] === $next['native_text'], 'native_text_readback_mismatch');
        pl_require_self_links($after['text'], $after['markup'], $next['native_markup'], $allowed);
        pl_check($after['photo'] === $before['photo'] && pl_canonical($after['buttons']) === pl_canonical($before['buttons']), 'native_media_or_cta_changed');
        $store->finish($row, 'verified', ['readback' => true, 'native_text_sha256' => hash('sha256', $after['text']),
            'native_markup_sha256' => pl_digest($after['markup']), 'native_autolinks' => count($next['native_markup']),
            'photo_preserved' => true, 'single_cta_preserved' => true, 'provider_acknowledged' => $acknowledged,
            'public_acceptance' => 'pending']);
        $saved = $store->operation(pl_key($id), 'links');
        pl_check(is_array($saved) && $saved['state'] === 'verified' && (int)$saved['write_attempts'] === 1, 'verified_operation_unavailable');
        $expectedRows[array_key_last($expectedRows)] = $saved; $active = null; ++$completed; $guard();
        pl_emit(['ok' => true, 'record' => 'post_native_verified', 'post_id' => $id, 'url' => $after['url'],
            'operation_key' => pl_key($id), 'payload_sha256' => $saved['payload_sha256'],
            'native_text_sha256' => hash('sha256', $after['text']), 'native_markup_sha256' => pl_digest($after['markup']),
            'native_autolinks' => count($next['native_markup']), 'photo_id' => $after['photo'],
            'single_cta_preserved' => true, 'copy_shortened' => $next['copy_shortened'],
            'completed_posts' => $completed, 'provider_acknowledged' => $acknowledged, 'automatic_retry' => false]);
    }
    pl_check($completed === 68 && $edits === 68 && count($store->rows()) === 431, 'remaining_operation_count_changed');
    $auditLinks = 0; $auditPosts = 0;
    // Independent final reads include the accepted X canary, which this source never edits.
    foreach ($package['posts'] as $id => $target) {
        $currentPost = $id; $seen = $observe($target); $next = $target['after'];
        pl_check($seen['text'] === $next['native_text'], 'final_native_text_changed');
        pl_require_self_links($seen['text'], $seen['markup'], $next['native_markup'], $allowed);
        pl_check(pl_canonical($seen['buttons']) === pl_canonical($baseline[$id]['buttons']), 'final_single_cta_changed');
        ++$auditPosts; $auditLinks += count($next['native_markup']);
        pl_emit(['ok' => true, 'record' => 'native_post_audit', 'post_id' => $id, 'mid' => $seen['mid'], 'url' => $seen['url'],
            'native_text' => $seen['text'], 'native_markup' => $seen['markup'],
            'native_text_sha256' => hash('sha256', $seen['text']), 'native_markup_sha256' => pl_digest($seen['markup']),
            'photo_id' => $seen['photo'], 'cta_label' => $target['cta_label'], 'cta_url' => $target['cta_url'],
            'single_cta_preserved' => true, 'changed_by_this_source' => $id !== PL_CANARY_POST]);
    }
    $guard(); pl_check($auditPosts === 69 && $auditLinks === 272, 'final_audit_incomplete');
    pl_emit(['ok' => true, 'state' => 'remaining_native_verified_pending_public_acceptance', 'revision' => PL_REVISION,
        'package_sha256' => PL_PACKAGE_SHA256, 'application_sha' => PL_APP, 'changed_posts' => 68, 'changed_links' => 268,
        'audited_posts' => 69, 'audited_links' => 272, 'approved_photos_preserved' => 69, 'single_ctas_preserved' => 69,
        'prior_operations_preserved' => 363, 'prior_operations_sha256' => $originalDigest, 'verified_operations' => 431,
        'canary_operation_preserved' => true, 'canary_rewritten' => false, 'pin_mid' => PL_PIN, 'pin_preserved' => true,
        'provider_edits' => $edits, 'provider_creates' => 0, 'provider_uploads' => 0, 'automatic_retry' => false]);
} catch (Throwable $error) {
    if ($store instanceof AppleService39PilotPublicationStore && is_array($active)) {
        try {
            $current = $store->operation($active['post_key'], $active['operation']);
            if (is_array($current) && in_array($current['state'], ['write_started','unknown'], true)
                && $current['payload_sha256'] === $active['payload_sha256']) {
                $store->finish($current, 'unknown', $current['outcome'] + ['reason' => pl_reason($error),
                    'provider_acknowledged' => $acknowledged, 'automatic_retry' => false]);
            }
        } catch (Throwable $ignored) { /* The durable claim remains held; no generic reconcile or resend. */ }
    }
    pl_emit(['ok' => false, 'state' => 'remaining_stopped', 'reason' => pl_reason($error), 'post_id' => $currentPost,
        'completed_posts' => $completed, 'provider_edits_attempted' => $edits,
        'error_class' => get_class($error), 'line' => $error->getLine(), 'automatic_retry' => false]); exit(1);
}
